class SelectModeFunctions:
    def __init__(self, top):
        self.top = top
        self.selected_mode = None

    def select_mode(self, mode):
        self.selected_mode = mode
        self.reset_button_colors()
        if mode == 1:
            self.top.Mode1.configure(bg="lightblue")
        elif mode == 2:
            self.top.Mode2.configure(bg="lightblue")
        else:
            self.top.Mode3.configure(bg="lightblue")
        self.update_ok_button_state()

    def reset_button_colors(self):
        self.top.Mode1.configure(bg="SystemButtonFace")
        self.top.Mode2.configure(bg="SystemButtonFace")
        self.top.Mode3.configure(bg="SystemButtonFace")

    def update_ok_button_state(self):
        if self.selected_mode is not None and self.top.save_path_entry.get():
            self.top.ok_button.configure(state=tk.NORMAL)
        else:
            self.top.ok_button.configure(state=tk.DISABLED)

    def proceed(self):
        folder_path = self.top.save_path_entry.get()
        try:
            os.makedirs(folder_path, exist_ok=True)
        except Exception as e:
            print(f"Error creating directory: {e}")

        if self.selected_mode == 1:
            self.show_mode1(self.top.top, folder_path)
        elif self.selected_mode == 2:
            self.show_mode2(self.top.top, folder_path)
        elif self.selected_mode == 3:
            self.show_mode3(self.top.top, folder_path)

    def select_folder(self):
        folder_selected = filedialog.askdirectory()
        if folder_selected:
            self.top.save_path_entry.delete(0, tk.END)
            self.top.save_path_entry.insert(0, folder_selected)
            self.update_ok_button_state()

