class RaspberryPiController:
    def __init__(self, w1):
        self.w1 = w1
        self.parameter_history = []
        self.load_config()
        self.file_path_list = []  # Initialize before first use
        self.queue = queue.Queue()
        self.current_thread = None  # Store the thread object
        self.latest_file_path, self.parameter_dict = self.load_latest_file_path()
        self.zoom_ax = None
        self.stop_file_remote = os.path.dirname(self.pi_python_file) + "/stop_rpi_control"
        self.is_wash = False
        self.stop = False

    def get_result_from_pi(self):
        try:
            import paramiko
            from scp import SCPClient
            import os
            import sys
            import time
            import tkinter.messagebox as messagebox

            print("[INFO] Connecting to the Raspberry Pi and downloading the latest acquisition...")

            client = paramiko.SSHClient()
            client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            client.connect(
                self.pi_address, username=self.pi_user, password=self.pi_password, timeout=3
            )

            # Find the latest date-organized acquisition directory
            command = "ls -td " + shlex.quote(self.pi_data_dir.rstrip("/")) + "/*/*/ | head -n 1"
            stdin, stdout, stderr = client.exec_command(command)
            latest_folder = stdout.read().decode().strip()
            print(f"[DEBUG] Latest acquisition directory: {latest_folder}")

            if not latest_folder:
                raise Exception(
                    "No acquisition directory was found. Spectra may not have been generated yet."
                )

            # Copy the complete acquisition directory through SCP
            scp = SCPClient(client.get_transport())
            local_path = self.local_file  # Destination directory selected in the GUI
            scp.get(latest_folder, recursive=True, local_path=local_path)

            # Collect all spectrum text-file paths from the downloaded directory
            saved_folder_name = os.path.basename(os.path.normpath(latest_folder))
            full_local_folder = os.path.join(local_path, saved_folder_name)

            self.file_path_list = []
            for root, dirs, files in os.walk(full_local_folder):
                for file in files:
                    if file.endswith(".txt"):
                        self.file_path_list.append(os.path.join(root, file))

            if not self.file_path_list:
                print("[WARNING] No spectrum text files were downloaded")
            else:
                print(f"[INFO] Retrieved {len(self.file_path_list)} spectra")

            self.latest_file_path[self.counted_param_str] = self.file_path_list
            self.save_latest_file_path()

            scp.close()
            client.close()

        except Exception as e:
            print(f"[ERROR] Acquisition download failed: {e}")
            sys.stdout.flush()
            messagebox.showerror("Error", f"File transfer failed: \n{str(e)}")

    def load_config(self):
        settings = load_settings()
        self.pi_user = settings["pi_user"]
        self.pi_address = settings["pi_address"]
        self.pi_python_file = settings["pi_python_file"]
        self.pi_password = settings["pi_password"] or None
        self.pi_data_dir = settings["pi_data_dir"]

    def change_save_path(self):
        folder_selected = filedialog.askdirectory()
        if folder_selected:
            self.w1.save_path_text.delete(0, tk.END)
            self.w1.save_path_text.insert(0, folder_selected)

    def start(self, *args):
        if not debug:
            if self.w1:
                self.w1.start_button.config(state=tk.DISABLED)
                self.w1.stop_button.config(state=tk.NORMAL)
                entries = {
                    "Ontime": (self.w1.ontime_entry, float),
                    "Offtime": (self.w1.offtime_entry, int),
                    "Cycle": (self.w1.cycle_entry, int),
                    "Integration Time": (self.w1.integration_time_entry, int),
                    "Spectra Interval": (self.w1.spectra_interval_entry, int),
                    "Voltage": (self.w1.voltage_entry, int),
                    "Conductivity": (self.w1.conductivity_entry, int),
                    "Loopnum": (self.w1.loop_entry, int),
                }

                metal_entries = {
                    "Metal1": (self.w1.metal_entry_1, float),
                    "Metal2": (self.w1.metal_entry_2, float),
                    "Metal3": (self.w1.metal_entry_3, float),
                    "Metal4": (self.w1.metal_entry_4, float),
                    "Metal5": (self.w1.metal_entry_5, float),
                }

                self.values = {}
                self.errors = []

                for name, (entry, value_type) in entries.items():
                    try:
                        self.values[name] = value_type(entry.get())
                    except:
                        self.errors.append(name)

                for name, (entry, value_type) in metal_entries.items():
                    try:
                        entry_value = entry.get()
                        if entry_value == "":
                            self.values[name] = 0.0
                        else:
                            self.values[name] = value_type(entry_value)
                    except:
                        self.errors.append(name)

                # Store the selected acquisition mode
                selected_mode = self.w1.select_mode
                if selected_mode is not None:
                    self.values["Selected Mode"] = selected_mode
                else:
                    self.errors.append("Selected Mode")

                self.values["Wash"] = self.is_wash

                if self.errors:
                    messagebox.showerror(
                        "Error",
                        "Invalid values in the following fields: \n" + "\n".join(self.errors),
                    )
                    self.w1.start_button.config(state=tk.NORMAL)
                    self.w1.stop_button.config(state=tk.DISABLED)
                    return None

                else:
                    self.update_parameter_history()  # Update the parameter-history menu
                    self.local_file = self.w1.save_path_text.get()
                    os.makedirs(
                        self.local_file, exist_ok=True
                    )  # Ensure that the local destination directory exists

                    print(
                        f"{self.count} =============================\nAcquisition is running on the Raspberry Pi"
                    )
                    thread = Thread(target=self.run_pi_commands)
                    thread.start()
                    self.queue.put(thread)  # Queue the thread for status monitoring
                    self.end_of_pi()  # Start monitoring the acquisition thread
                    return self.values
        else:
            self.local_file = self.w1.save_path_text.get()
            file_path_list = []
            for filename in os.listdir(self.local_file):
                if filename.endswith(".txt"):
                    file_path = os.path.join(self.local_file, filename)
                    file_path_list.append(file_path)
            self.latest_file_path["123"] = file_path_list
            self.counted_param_str = "123"
            self.nor_point_index = None
            self.w1.spectrum_combobox.set("123")
            if self.w1.spectrum_combobox.get():
                self.update_plot()

    def run_pi_commands(self):
        try:
            if self.send_to_pi(self.values) and not self.stop:
                sys.stdout.write("Starting file transfer\n")
                sys.stdout.flush()
                self.get_result_from_pi()
        finally:
            self.queue.put("thread_finished")

    def update_parameter_history(self):
        # Serialize the current parameters and append them to the history
        # Parameter serialization order
        ordered_keys = [
            "Voltage",
            "Ontime",
            "Offtime",
            "Cycle",
            "Conductivity",
            "Metal1",
            "Metal2",
            "Metal3",
            "Metal4",
            "Metal5",
        ]
        ordered_values = []
        for key in ordered_keys:
            if key in self.values:
                ordered_values.append(str(self.values[key]))
        param_str = "_".join(ordered_values)
        self.count = len(self.parameter_history) + 1
        self.counted_param_str = format_title(f"({self.count}) {param_str}")
        self.parameter_history.insert(0, self.counted_param_str)
        self.w1.parameter_combobox["values"] = self.parameter_history
        self.w1.spectrum_combobox["values"] = self.parameter_history
        self.w1.spectrum_combobox.set(self.counted_param_str)
        self.parameter_dict[self.counted_param_str] = self.values

    def update_entries_from_combobox(self, event):
        parameter = self.parameter_dict[self.w1.parameter_combobox.get()]
        entries = {
            self.w1.ontime_entry: parameter["Ontime"],
            self.w1.offtime_entry: parameter["Offtime"],
            self.w1.cycle_entry: parameter["Cycle"],
            self.w1.integration_time_entry: parameter["Integration Time"],
            self.w1.spectra_interval_entry: parameter["Spectra Interval"],
            self.w1.voltage_entry: parameter["Voltage"],
            self.w1.conductivity_entry: parameter["Conductivity"],
            self.w1.loop_entry: parameter["Loopnum"],
            self.w1.metal_entry_1: parameter["Metal1"],
            self.w1.metal_entry_2: parameter["Metal2"],
            self.w1.metal_entry_3: parameter["Metal3"],
            self.w1.metal_entry_4: parameter["Metal4"],
            self.w1.metal_entry_5: parameter["Metal5"],
        }

        for entry, value in zip(entries.keys(), entries.values()):
            entry.delete(0, tk.END)
            entry.insert(0, value)

    # The effective UART/GPIO sender is defined below.

    def send_to_pi(self, parameter):
        import json, time, sys
        import paramiko
        from tkinter import messagebox

        parameter_json = json.dumps(parameter)
        client = paramiko.SSHClient()
        client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        try:
            # Open the SSH connection
            client.connect(
                self.pi_address, username=self.pi_user, password=self.pi_password, timeout=3
            )

            # Use the configured remote controller path
            trigger_path = self.pi_python_file
            command = (
                "sudo python3 -u " + shlex.quote(trigger_path) + " " + shlex.quote(parameter_json)
            )

            print(f"[DEBUG] Executing the Raspberry Pi command: {command}")
            sys.stdout.flush()

            # Open an SSH channel
            transport = client.get_transport()
            channel = transport.open_session()
            channel.get_pty()
            channel.exec_command(command)

            stdout_data = ""
            stderr_data = ""

            # Continue reading output until completion
            while (
                not channel.exit_status_ready()
                or channel.recv_ready()
                or channel.recv_stderr_ready()
            ):
                if channel.recv_ready():
                    chunk = channel.recv(4096)
                    if chunk:
                        try:
                            text = chunk.decode("utf-8")
                        except UnicodeDecodeError:
                            text = chunk.decode("latin-1")
                        stdout_data += text
                        sys.stdout.write(text)
                        sys.stdout.flush()
                if channel.recv_stderr_ready():
                    chunk = channel.recv_stderr(4096)
                    if chunk:
                        try:
                            text = chunk.decode("utf-8")
                        except UnicodeDecodeError:
                            text = chunk.decode("latin-1")
                        stderr_data += text
                        sys.stdout.write(text)
                        sys.stdout.flush()
                time.sleep(0.1)

            exit_status = channel.recv_exit_status()
            if exit_status != 0:
                raise RuntimeError(
                    f"Remote controller exited with status {exit_status}. "
                    "Review the acquisition log before retrying."
                )
            return True

        except Exception as e:
            sys.stdout.write(f"Connection or remote execution failed: {str(e)}\n")
            sys.stdout.flush()
            messagebox.showerror(
                "UART/GPIO error", f"Connection or remote execution failed:\n{str(e)}"
            )
            return False

        finally:
            client.close()

    def end_of_pi(self):
        try:
            message = self.queue.get_nowait()
            if isinstance(message, Thread):  # A thread object was queued by start()
                self.current_thread = message  # Store the thread object
            elif message == "thread_finished" and not self.stop:
                if self.file_path_list:
                    self.latest_file_path[self.counted_param_str] = (
                        self.file_path_list
                    )  # Store the acquisition files for this parameter set
                    self.save_latest_file_path()
                    self.w1.start_button.config(state=tk.NORMAL)  # Update the GUI state
                    try:
                        self.selected_condition = self.w1.spectrum_combobox.get()
                        if self.latest_file_path[self.selected_condition]:
                            self.nor_point_index = None
                            self.update_plot()
                        return  # Stop polling
                    except Exception as e:
                        # print(f'Cannot find txt files, {e}')
                        sys.stdout.flush()
            elif message == "thread_finished" and self.stop:
                self.w1.start_button.config(state=tk.NORMAL)
                self.stop = False
                return
        except queue.Empty:
            pass

        if (
            self.current_thread and self.current_thread.is_alive()
        ):  # Continue polling while the thread is active
            self.w1.start_button.after(100, self.end_of_pi)  # Schedule the next status check
        else:
            self.w1.start_button.config(
                state=tk.NORMAL
            )  # Restore the GUI after the thread completes

